-- GenDB engine variant Q05-from_permutation: template q05.sql, kind from_permutation (generated by generate.py; frozen)
SELECT
  n_name,
  SUM(l_extendedprice * (
    1 - l_discount
  )) AS revenue
FROM region, nation, supplier, lineitem, orders, customer
WHERE
  c_custkey = o_custkey
  AND l_orderkey = o_orderkey
  AND l_suppkey = s_suppkey
  AND c_nationkey = s_nationkey
  AND s_nationkey = n_nationkey
  AND n_regionkey = r_regionkey
  AND r_name = $1
  AND o_orderdate >= $2
  AND o_orderdate < $2 + INTERVAL '1 YEAR'
GROUP BY
  n_name
ORDER BY
  revenue DESC
